using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
partial class TerminalWindow {
 static readonly string[] MemoAliases={"下班倒计时","专注","待办计划","提醒","健康","文件观察","进程监控","Codex状态","通知记录","通知中心"};
 string memoTab="资源预警";
 TextBox MemoPoints(Panel parent,string title,IEnumerable<double> values,double min,double max,string preset){
  var section=new StackPanel{Margin=new Thickness(0,0,0,14)};parent.Children.Add(section);section.Children.Add(Text(title,14));var input=TaskbarName(new TextBox{Text=ThresholdPoints.Format(values),MaxLength=200,Margin=new Thickness(0,4,0,6)},title+"预警点");section.Children.Add(input);var add=TaskbarRange(section,"选择或输入一个点",min,min,max);var actions=new WrapPanel();section.Children.Add(actions);Button(actions,"＋加入提醒点",()=>{double point=TaskbarNumber(add);input.Text=ThresholdPoints.Format(ThresholdPoints.Parse(input.Text+", "+point.ToString(System.Globalization.CultureInfo.InvariantCulture),min,max));});Button(actions,"使用推荐点",()=>input.Text=preset);var chips=new WrapPanel();section.Children.Add(chips);Action render=()=>{chips.Children.Clear();try{foreach(double point in ThresholdPoints.Parse(input.Text,min,max)){double v=point;var chip=Button(chips,point+" ×",()=>input.Text=ThresholdPoints.Format(ThresholdPoints.Parse(input.Text,min,max).Where(p=>p!=v)));chip.Padding=new Thickness(8,3,8,3);chip.MinHeight=26;chip.ToolTip="删除这个提醒点";}}catch(ArgumentException){}};input.TextChanged+=(s,e)=>render();render();return input;
 }
 void BuildMemo(){var nav=new WrapPanel{Margin=new Thickness(0,0,0,10)};var host=new ContentControl{HorizontalContentAlignment=HorizontalAlignment.Stretch};content.Children.Add(nav);content.Children.Add(host);var names=new[]{"提醒方式","资源预警","额度与重置","下班倒计时","提醒","健康","专注","待办计划","文件观察","进程监控","Codex状态","系统通知","通知记录"};var buttons=new Dictionary<string,Button>();Action<string> select=title=>{monitorChecks.Clear();memoTab=title;host.Content=MemoSection(title);foreach(var pair in buttons)pair.Value.Tag=pair.Key==title?"selected":null;TerminalAppearance.BindTree(host);VisualEffects.Apply(host);RefreshMonitor();};foreach(string title in names){string name=title;buttons[name]=Button(nav,name,()=>select(name));}select(names.Contains(memoTab)?memoTab:"资源预警");}
 FrameworkElement MemoSection(string title){StackPanel body;var frame=Panel(title=="资源预警"?"侦探警戒线 · 多级阈值":title,"bell",out body);var cfg=assistant.Config.Monitor;
  if(title=="提醒方式"){
   SettingsLabel(body,"全部提醒的总开关与音量");MonitorToggle(body,"显示柯南对话气泡",()=>assistant.Config.Bubbles,v=>assistant.Config.Bubbles=v);if(Voices!=null){var voice=TaskbarCheck(body,"柯南原声总开关",Voices.Settings.Enabled);voice.Click+=(s,e)=>{Voices.Settings.Enabled=voice.IsChecked==true;Voices.Apply();};var volume=TaskbarRange(body,"原声音量（%）",Math.Round(Voices.Settings.Volume*100),0,100);volume.TextChanged+=(s,e)=>{int v;if(Int32.TryParse(volume.Text,out v)&&v>=0&&v<=100){Voices.SetVolume(v/100.0);Voices.Apply();}};}
   SettingsLabel(body,"资源及额度的提醒方式");MonitorToggle(body,"资源及额度提醒显示气泡",()=>cfg.AlertBubbles,v=>cfg.AlertBubbles=v);MonitorToggle(body,"资源及额度提醒播放原声",()=>cfg.AlertSound,v=>cfg.AlertSound=v);MonitorToggle(body,"资源及额度提醒显示动作",()=>cfg.AlertActions,v=>cfg.AlertActions=v);SettingDescription(body,"关闭气泡或声音后仍记录事件。下班的数字手势与原声可在下班标签单独控制；全屏静音、原声音量及已有通知授权规则继续生效。文件变更、进程退出和系统通知属于事件提醒，使用开关，不设置没有含义的数值阈值。");
  }else if(title=="资源预警"){
   MonitorToggle(body,"启用资源预警",()=>cfg.Alerts,v=>cfg.Alerts=v);SettingDescription(body,"每项最多12个点，可直接输入、滑块添加、选推荐点或点击色块删除。每级分别持续确认和去重，恢复至阈值92%以下后重新布防；未知读数不报警。");
   BuildProcessReporting(body);
   var editors=new List<Tuple<MonitorRule,CheckBox,TextBox>>();foreach(var rule in cfg.Rules.Where(r=>r!=null)){double max=rule.Unit=="%"?100:rule.Unit=="°C"?150:100000;var section=new StackPanel();var enabled=TaskbarCheck(section,rule.Label+"（"+rule.Unit+"）",rule.Enabled);var points=MemoPoints(section,rule.Label,ThresholdPoints.Effective(rule.Thresholds,rule.Threshold,.01,max),.01,max,rule.Unit=="%"?"70, 85, 95":rule.Unit=="°C"?"70, 80, 90":"10, 30, 50");body.Children.Add(new Expander{Header=rule.Label+" · 展开设置多个点",Content=section,Margin=new Thickness(0,5,0,5)});editors.Add(Tuple.Create(rule,enabled,points));}
   SettingsLabel(body,"持续确认与冷却");var hold=TaskbarRange(body,"持续秒数",cfg.HoldSeconds,3,300);var cooldown=TaskbarRange(body,"同级冷却秒数",cfg.CooldownSeconds,30,3600);Button(body,"保存资源提醒设置",()=>{var updated=new List<MonitorRule>();foreach(var entry in editors){var r=entry.Item1;var points=ThresholdPoints.Parse(entry.Item3.Text,.01,r.Unit=="%"?100:r.Unit=="°C"?150:100000);updated.Add(new MonitorRule{Key=r.Key,Label=r.Label,Unit=r.Unit,Enabled=entry.Item2.IsChecked==true,Threshold=points[0],Thresholds=points.ToList()});}int h=TaskbarInt(hold),c=TaskbarInt(cooldown);if(h<3||h>300||c<30||c>3600)throw new ArgumentException("持续3–300秒，冷却30–3600秒。");SaveMonitor(()=>{cfg.Rules=updated;cfg.HoldSeconds=h;cfg.CooldownSeconds=c;});});
  }else if(title=="额度与重置"){
   var q=cfg.Quota;MonitorToggle(body,"剩余额度不足时提醒",()=>q.Alerts,v=>q.Alerts=v);MonitorToggle(body,"额度即将重置时提醒",()=>q.ResetReminder,v=>q.ResetReminder=v);var five=MemoPoints(body,"五小时剩余额度（%）",ThresholdPoints.Effective(q.FiveHourThresholds,q.FiveHourThreshold,0,100),0,100,"5, 10, 20");var week=MemoPoints(body,"周剩余额度（%）",ThresholdPoints.Effective(q.WeeklyThresholds,q.WeeklyThreshold,0,100),0,100,"5, 10, 20");var reset=MemoPoints(body,"重置前提醒（分钟）",(q.ResetReminderPoints??new List<int>{q.ResetReminderMinutes}).Select(x=>(double)x),1,1440,"1, 5, 15, 30");SettingDescription(body,"剩余额度下降到各点分别提醒；同周期去重。重置前多个时间点分别提醒，休眠或首次打开错过多个点时只发最近的一次。原声提示不重复朗读每秒倒计时。");Button(body,"保存额度与重置提醒",()=>{var f=ThresholdPoints.Parse(five.Text,0,100);var w=ThresholdPoints.Parse(week.Text,0,100);var points=ThresholdPoints.Parse(reset.Text,1,1440);if(points.Any(x=>x!=Math.Floor(x)))throw new ArgumentException("提前分钟请输入整数。");SaveMonitor(()=>{q.FiveHourThresholds=f.ToList();q.WeeklyThresholds=w.ToList();q.FiveHourThreshold=f[0];q.WeeklyThreshold=w[0];q.ResetReminderPoints=points.Select(x=>(int)x).ToList();q.ResetReminderMinutes=q.ResetReminderPoints[0];});});var connection=new StackPanel();BuildQuotaSettings(connection,cfg);body.Children.Add(new Expander{Header="额度连接、授权与重置记录",Content=connection,Margin=new Thickness(0,10,0,0)});
  }else if(title=="系统通知"){
   MonitorToggle(body,"网络连接变化时提醒",()=>assistant.Config.NetworkAlerts,v=>assistant.Config.NetworkAlerts=v);SystemNotificationUI(body);var parent=notices.Parent as Panel;if(parent!=null)parent.Children.Remove(notices);body.Children.Add(notices);
  }else if(ToolPage!=null){
   if(title=="进程监控"){MonitorToggle(body,"进程资源超限时提醒",()=>assistant.Config.ProcessAlerts,v=>assistant.Config.ProcessAlerts=v);MonitorToggle(body,"进程退出时提醒",()=>assistant.Config.ProcessExitAlerts,v=>assistant.Config.ProcessExitAlerts=v);var cpuPoints=MemoPoints(body,"进程CPU（%）",ThresholdPoints.Effective(assistant.Config.ProcessCpuPoints,assistant.Config.CpuThreshold,.01,100),.01,100,"60, 80, 95");var memPoints=MemoPoints(body,"进程内存（MiB）",ThresholdPoints.Effective(assistant.Config.ProcessMemoryPoints,assistant.Config.MemoryThreshold,.01,1000000),.01,1000000,"1024, 2048, 4096");Button(body,"保存进程提醒点",()=>{var c=ThresholdPoints.Parse(cpuPoints.Text,.01,100);var m=ThresholdPoints.Parse(memPoints.Text,.01,1000000);SaveMonitor(()=>{assistant.Config.ProcessCpuPoints=c.ToList();assistant.Config.ProcessMemoryPoints=m.ToList();});});}
   if(title=="Codex状态")MonitorToggle(body,"Codex确需确认或中断时提醒",()=>assistant.Config.CodexAlerts,v=>assistant.Config.CodexAlerts=v);

   Border cached;if(!embeddedPages.TryGetValue(title,out cached)){var tool=ToolPage(title);PrepareToolPage(tool,title);cached=new Border{Child=tool};embeddedPages[title]=cached;}var old=cached.Parent as Panel;if(old!=null)old.Children.Remove(cached);body.Children.Add(cached);
   if(title=="健康"||title=="专注"||title=="待办计划")BuildMemoTimePoints(body,title);
  }
  return frame;
 }
 void BuildMemoTimePoints(Panel body,string title){var current=title=="健康"?skills.Engine.Data.WellnessAdvanceMinutes:title=="专注"?skills.Engine.Data.Focus.AdvanceMinutes:advanced.Engine.Data.TaskAdvanceMinutes;var points=MemoPoints(body,title+"提前提醒（分钟）",(current==null||current.Count==0?new List<int>{0}:current).Select(x=>(double)x),0,1440,"1, 3, 5");SettingDescription(body,"0表示仅保留到点提醒；大于0的点为提前提醒。健康提醒的提前点需小于该次间隔；专注的提前点小于该阶段时长。已有到点提醒继续生效。");Button(body,"保存"+title+"提前提醒点",()=>{var values=ThresholdPoints.Parse(points.Text,0,1440);if(values.Any(x=>x!=Math.Floor(x)))throw new ArgumentException("提前分钟请输入整数。");var list=values.Where(x=>x>0).Select(x=>(int)x).ToList();if(title=="健康")skills.Engine.Data.WellnessAdvanceMinutes=list;else if(title=="专注")skills.Engine.Data.Focus.AdvanceMinutes=list;else advanced.Engine.Data.TaskAdvanceMinutes=list;if(title=="待办计划")advanced.Save();else skills.Save();});}
}
